class Solution {
public:
    long long numberOfSubarrays(vector<int>& nums) {
        long long ans = 0;
        vector<pair<int, int>> stack;
        for (int x : nums) {
            while (!stack.empty() && stack.back().first < x) {
                stack.pop();
            }
            if (!stack.empty() && stack.back().first == x) {
                stack.back().second++;
                ans += stack.back().second;
            } else {
                stack.push_back({x, 1});
                ans += 1;
            }
        }
        return ans;
    }
};

class Solution {
    public long numberOfSubarrays(int[] nums) {
        long ans = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        for (int x : nums) {
            while (!stack.isEmpty() && stack.peek()[0] < x) {
                stack.pop();
            }
            if (!stack.isEmpty() && stack.peek()[0] == x) {
                stack.peek()[1]++;
                ans += stack.peek()[1];
            } else {
                stack.push(new int[]{x, 1});
                ans += 1;
            }
        }
        return ans;
    }
}

var numberOfSubarrays = function(nums) {
    let ans = 0;
    const stack = [];
    for (const x of nums) {
        while (stack.length > 0 && stack[stack.length - 1][0] < x) {
            stack.pop();
        }
        if (stack.length > 0 && stack[stack.length - 1][0] === x) {
            stack[stack.length - 1][1]++;
            ans += stack[stack.length - 1][1];
        } else {
            stack.push([x, 1]);
            ans += 1;
        }
    }
    return ans;
};
